'use strict';
// Local Auto Farm runs only while this game is open and unpaused.
const autoButton=document.createElement('button');autoButton.id='autoFarmBtn';autoButton.className='auto-farm-button';autoButton.onclick=openAutoPanel;$('playScreen').append(autoButton);
function updateAutoHUD(){autoButton.textContent=(autoFarmActive()?'AUTO · ':'AUTO ')+autoTimeText(player.autoFarm.seconds);autoButton.classList.toggle('running',autoFarmActive());autoButton.setAttribute('aria-label','Auto Farm · '+autoTimeText(player.autoFarm.seconds));const clock=$('autoFarmClock');if(clock)clock.textContent=autoTimeText(player.autoFarm.seconds)}
function openAutoPanel(){
 const body=document.createElement('div');body.className='auto-panel';const clock=document.createElement('div');clock.className='auto-clock';clock.innerHTML='<small>เวลาคงเหลือ</small><strong id="autoFarmClock"></strong><small>สูงสุด 24 ชั่วโมง</small>';clock.querySelector('strong').textContent=autoTimeText(player.autoFarm.seconds);body.append(clock);
 const right=document.createElement('div');right.className='auto-options';const slots=document.createElement('div');slots.className='auto-slots';for(let i=0;i<4;i++){const button=document.createElement('button'),id=player.autoFarm.skills[i];button.setAttribute('aria-label','ตั้งสกิล Auto ช่อง '+(i+1));button.innerHTML='<small>'+(i+1)+'</small><span></span>';button.querySelector('span').textContent=id?WEAPON_SKILLS[id].name:'เลือกสกิล';button.disabled=autoFarmActive();button.onclick=()=>openAutoPicker(i);slots.append(button)}right.append(slots);
 const note=document.createElement('p');note.textContent='วนใช้ 1 → 2 → 3 → 4 · ข้ามช่องที่ใช้ไม่ได้ · ไม่กดบัฟ · ต้องเปิดเกมไว้';right.append(note);
 const actions=document.createElement('div');actions.className='auto-actions';const help=document.createElement('button');help.textContent='คำอธิบาย';help.onclick=()=>modal('การ Auto Farm','เลือก Active 4 ช่องตามลำดับของคุณ หากติด CD หรือ MP ไม่พอจะลองช่องถัดไปทันที ไม่กดบัฟและไม่ใช้ยาเอง ชาร์จจนเต็ม และใช้สกิลกดค้างครั้งละ 3 วินาที\nทำงานเฉพาะด่านที่เริ่ม Auto ไม่เปลี่ยนด่านเอง แพ้หรือเวลาหมดจะหยุด\nต้องเปิดเกมไว้และให้เกมทำงานอยู่ พักเกม สลับแท็บ หรือดับจอจะไม่ฟาร์มและไม่หักเวลา ปิดเกมแล้วเปิดใหม่จะไม่มีรางวัลย้อนหลัง ต้องกดเริ่ม Auto ใหม่\nใบละ 1 ชั่วโมง ราคา 10,000 เงิน กดใช้ใบสะสมได้สูงสุด 24 ชั่วโมง',[['กลับ',openAutoPanel]]);
 const toggle=document.createElement('button');toggle.id='autoFarmToggle';toggle.className='primary';toggle.textContent=autoFarmActive()?'หยุด Auto':'เริ่ม Auto';toggle.disabled=!autoFarmActive()&&(!run||run.tutorial||run.finished||player.autoFarm.seconds<=0||!player.autoFarm.skills.some(id=>id&&weaponSkillEnabled(id)));toggle.onclick=()=>{if(autoFarmActive()){stopAutoFarm();openAutoPanel()}else if(startAutoFarm()){closeModal();updateAutoHUD();toast('เริ่ม Auto · เปิดเกมไว้เพื่อฟาร์ม')}};actions.append(help,toggle);right.append(actions);
 const ticket=document.createElement('button');ticket.id='useAutoTicket';ticket.textContent='ใช้ใบ Auto Farm · มี '+player.autoFarm.tickets+' ใบ';ticket.disabled=!player.autoFarm.tickets||player.autoFarm.seconds+AUTO_TICKET_SECONDS>AUTO_MAX_SECONDS;ticket.onclick=()=>{if(activateAutoTicket())openAutoPanel()};right.append(ticket);body.append(right);
 if(!run){const hint=document.createElement('small');hint.textContent='เลือกสกิลและใช้ใบได้ที่นี่ จากนั้นเข้าด่านที่ต้องการแล้วกดเริ่ม Auto';right.append(hint)}
 modal('Auto Farm'+(run&&!run.tutorial?' · '+(run.trial?TRIAL:stageById(run.id)).name:''),body,[]);$('modal').classList.add('auto-modal');
}
function openAutoPicker(index){const body=document.createElement('div');body.className='auto-picker';for(const id of [null,...Object.values(WEAPON_SKILLS).filter(d=>d.kind==='active'&&weaponSkillEnabled(d.id)).map(d=>d.id)]){const button=document.createElement('button');button.textContent=id?WEAPON_SKILLS[id].name+' · ขั้น '+WEAPON_SKILLS[id].tier:'ว่าง';button.onclick=()=>{if(setAutoSkill(index,id))openAutoPanel()};body.append(button)}modal('เลือก Active · Auto ช่อง '+(index+1),body,[['กลับ',openAutoPanel]])}
const localAutoShop=openPotionShop;openPotionShop=function(){localAutoShop();const stock=document.querySelector('.shop-stock');if(!stock)return;const button=document.createElement('button');button.id='buyAutoTicket';button.className='shop-product';button.textContent='ใบ Auto Farm · 1 ชั่วโมง\n10,000 เงิน';button.onclick=()=>modal('ใบ Auto Farm','1 ใบ = 1 ชั่วโมง · ราคา 10,000 เงิน\nซื้อแล้วกดใช้ที่หน้า Auto หรือกระเป๋า เพื่อเพิ่มเวลาได้สูงสุด 24 ชั่วโมง\nต้องเปิดเกมไว้เพื่อฟาร์ม',[['กลับร้าน',openPotionShop],['ซื้อ 1 ใบ',()=>{if(buyAutoTickets(1)){toast('ได้รับใบ Auto Farm 1 ใบ');openPotionShop()}else toast('ซื้อไม่ได้ · เงินไม่พอ หรือใบในกระเป๋าเต็ม')},true]]);stock.append(button)};
const localAutoPress=press;press=function(code,repeat=false){if(autoFarmActive()&&!paused&&screen==='play'){stopAutoFarm('manualInput');toast('หยุด Auto · กลับมาควบคุมเอง')}return localAutoPress(code,repeat)};
const localAutoAssigned=castAssignedSkill;castAssignedSkill=function(slot){if(autoFarmActive()&&!paused)stopAutoFarm('manualInput');return localAutoAssigned(slot)};
$('touchJoystick').addEventListener('pointerdown',()=>{if(autoFarmActive()&&!paused)stopAutoFarm('manualInput')},true);
window.addEventListener('pagehide',()=>{stopAutoFarm('closed');save()});
updateAutoHUD();
